    if (sampleCovar == null) {
        return Double.NaN;
    }

    if (getFreeParameters().contains(parameter)) {
        if (getNumFreeParams() <= maxFreeParams) {
            if (parameter.getNodeA() != parameter.getNodeB()) {
                Node nodeA = parameter.getNodeA();
                Node nodeB = parameter.getNodeB();
                Node parent;
                Node child;

                Graph graph = getSemPm().getGraph();

                if (graph.isParentOf(nodeA, nodeB)) {
                    parent = nodeA;
                    child = nodeB;
                } else {
                    parent = nodeB;
                    child = nodeA;
                }

                if (child.getName().startsWith("E_")) {
                    return Double.NaN;
                }

                CovarianceMatrix cov = new CovarianceMatrix(this.measuredNodes, sampleCovar, this.sampleSize);
                Regression regression = new RegressionCovariance(cov);
                List<Node> parents = graph.getParents(child);

                parents.removeIf(node -> node.getName().startsWith("E_"));

                if (!(child.getNodeType() == NodeType.LATENT) && !containsLatent(parents)) {
                    RegressionResult result = regression.regress(child, parents);
                    double[] se = result.getSe();
                    return se[parents.indexOf(parent) + 1];
                }
            }

            if (this.sampleCovarC == null) {
                this.standardErrors = null;
                return Double.NaN;
            }

            int index = getFreeParameters().indexOf(parameter);
            double[] doubles = standardErrors();

            if (doubles == null) {
                return Double.NaN;
            }

            return doubles[index];
        } else {
            return Double.NaN;
        }
    } else if (getFixedParameters().contains(parameter)) {
        return 0.0;
    }

    throw new IllegalArgumentException(
            "That is not a parameter of this model: " + parameter);

public LinkedList<Double> getTotalEffects(Node x, Node y) {
    List<Node> parents = this.cpdag.getParents(x);
    List<Node> children = this.cpdag.getChildren(x);

    List<Node> siblings = new ArrayList<>(this.cpdag.getAdjacentNodes(x));
    siblings.removeAll(parents);
    siblings.removeAll(children);

    int size = siblings.size();
    SublistGenerator gen = new SublistGenerator(size, size);
    int[] choice;

    LinkedList<Double> totalEffects = new LinkedList<>();

    while ((choice = gen.next()) != null) {
        try {
            List<Node> siblingsChoice = GraphUtils.asList(choice, siblings);

            if (!isLegalParentSet(parents, siblingsChoice)) {
                continue;
            }

            double beta;

            if (idaType == IDA_TYPE.REGULAR) {
                beta = getRegularIdaBeta(x, y, parents, siblingsChoice);
            } else {
                beta = getOptimalIdaBeta(x, y, siblings, siblingsChoice);
            }

            totalEffects.add(beta);
        } catch (Exception e) {
            TetradLogger.getInstance().log(e.getMessage());
        }
    }

    Collections.sort(totalEffects);
    return totalEffects;

 * Pairwise check for a single (x, y).
 *
 * <p>Logic:
 * <ol>
 *   <li>validate inputs</li>
 *   <li>amenability check</li>
 *   <li>potentially-directed-path existence check</li>
 * </ol>
 *
 * <p>If there are no potentially directed paths from x to y, returns {@link Status#NO_PD_PATHS}
 * and callers should force total effect = 0 (and should not run regression).
 *
 * @param x the source node
 * @param y the target node
 * @return eligibility status and information
 */
public Eligibility checkPairwise(Node x, Node y) {
    if (x == null || y == null) {
        return new Eligibility(Status.INVALID_INPUT, "x or y is null", false, Collections.emptySet());
    }
    if (x.equals(y)) {
        return new Eligibility(Status.INVALID_INPUT, "x equals y", false, Collections.emptySet());
    }
    // Defensive: ensure nodes belong to the graph.
    // (Some code paths construct Nodes elsewhere; this avoids silent surprises.)
    if (graph.getNode(x.getName()) == null || graph.getNode(y.getName()) == null) {
        return new Eligibility(Status.INVALID_INPUT,
                "x or y is not in graph (by name lookup): x=" + x.getName() + ", y=" + y.getName(),
                false, Collections.emptySet());
    }

    boolean amenable = graph.paths().isGraphAmenable(x, y, graphType, maxPathLength, Set.of());
    if (!amenable) {
        return new Eligibility(Status.NOT_AMENABLE, "Graph is not amenable for (x,y)", false, Collections.emptySet());
    }

    Set<List<Node>> pdPaths = graph.paths().potentiallyDirectedPaths(x, y, maxPathLength);
    if (pdPaths == null || pdPaths.isEmpty()) {
        return new Eligibility(Status.NO_PD_PATHS,
                "No potentially directed paths from x to y (within maxPathLength)",
                true, Collections.emptySet());
    }

    return new Eligibility(Status.OK, null, true, pdPaths);

private void potentiallyDirectedPathsVisit(Node node1, Node node2,
                                           LinkedList<Node> path,
                                           Set<List<Node>> paths,
                                           int maxLength) {

    path.addLast(node1);

    // Now path.size() - 1 is the number of edges.
    if (maxLength != -1 && path.size() - 1 > maxLength) {
        path.removeLast();
        return;
    }

    // cycle check
    Set<Node> __path = new HashSet<>(path);
    if (__path.size() < path.size()) {
        path.removeLast();
        return;
    }

    if (path.size() > 1 && node1 == node2) {
        List<Node> _path = new LinkedList<>(path);
        paths.add(_path);
    }

    for (Edge edge : graph.getEdges(node1)) {
        Node child = Edges.traversePotentiallyDirected(node1, edge);
        if (child == null) continue;
        if (path.contains(child)) continue;   // forbid any repeats, including node2
        potentiallyDirectedPathsVisit(child, node2, path, paths, maxLength);
    }

    path.removeLast();

